import{_ as r,o as t,c as s,a3 as a}from"./chunks/framework.Crt1tuW8.js";const o="/BD1A26/assets/backup.7ZKiZqMu.png",i="/BD1A26/assets/backup-tables.C1SuQBr8.png",l="/BD1A26/assets/backup-options.C94PW3qn.png",g=JSON.parse('{"title":"06 — Import et export d’une base de données","description":"","frontmatter":{"title":"06 — Import et export d’une base de données","aside":false},"headers":[],"relativePath":"modules/02-ddl-base/07-import-export.md","filePath":"modules/02-ddl-base/07-import-export.md"}'),n={name:"modules/02-ddl-base/07-import-export.md"};function d(c,e,u,p,b,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_07-—-import-et-export-d-une-base-de-donnees" tabindex="-1">07 — Import et export d’une base de données <a class="header-anchor" href="#_07-—-import-et-export-d-une-base-de-donnees" aria-label="Permalink to &quot;07 — Import et export d’une base de données&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Savoir <strong>exporter</strong> et <strong>importer une base de données complète</strong> à l’aide de DBeaver afin de :</p><ul><li>sauvegarder un travail</li><li>remettre un projet</li><li>recréer une base de données existante</li></ul><hr><h2 id="exporter-une-base-de-donnees-dbeaver" tabindex="-1">Exporter une base de données (DBeaver) <a class="header-anchor" href="#exporter-une-base-de-donnees-dbeaver" aria-label="Permalink to &quot;Exporter une base de données (DBeaver)&quot;">​</a></h2><p>Exporter une base de données permet de sauvegarder :</p><ul><li>la structure (tables, contraintes, clés)</li><li>les données</li></ul><h3 id="etapes-d-exportation" tabindex="-1">Étapes d&#39;exportation <a class="header-anchor" href="#etapes-d-exportation" aria-label="Permalink to &quot;Étapes d&#39;exportation&quot;">​</a></h3><ul><li>Clic-droit sur la <strong>base de données</strong> dans DBeaver.</li><li>Dans l&#39;option <code>Outils</code>, choisir <code>Dump database</code></li><li>Cocher toutes les tables + <code>Suivant</code></li><li>Choisir le <code>Encoding</code> en <code>UTF-8</code></li><li>Cocher <code>Add DROP statements</code></li><li>Choisir et noter le <code>Output folder</code></li><li>Démarrage</li><li>Ouvir et valider le fichier <code>.sql</code> généré.</li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>À retenir</strong><br> Le fichier exporté doit être un fichier <code>.sql</code> lisible.<br> C&#39;est normal de ne pas comprendre toutes les instructions qui y sont contenues. </div><img src="'+o+'" alt="Backup" class="img-bordered mb-5"><img src="'+i+'" alt="Backup tables" class="img-bordered mb-5"><img src="'+l+`" alt="Backup options" class="img-bordered mb-5"><hr><h2 id="completer-le-fichier-exporte" tabindex="-1">Compléter le fichier exporté <a class="header-anchor" href="#completer-le-fichier-exporte" aria-label="Permalink to &quot;Compléter le fichier exporté&quot;">​</a></h2><p>Le fichier <code>.sql</code> généré par DBeaver contient :</p><ul><li>la création des tables, contraintes et clés</li><li>les données</li></ul><p>Mais il <strong>ne contient pas</strong> la création de la base de données elle-même, ni la sélection de celle-ci. Si on l&#39;exécute tel quel, MariaDB répond :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERROR 1046 (3D000): No database selected</span></span></code></pre></div><h3 id="ce-qu-il-faut-ajouter" tabindex="-1">Ce qu&#39;il faut ajouter <a class="header-anchor" href="#ce-qu-il-faut-ajouter" aria-label="Permalink to &quot;Ce qu&#39;il faut ajouter&quot;">​</a></h3><p>Ouvrez le fichier <code>.sql</code> dans un éditeur de texte (VS Code, Notepad++, ou DBeaver) et ajoutez ces <strong>deux lignes tout en haut</strong>, avant tout le reste :</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tp_evenements;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tp_evenements;</span></span></code></pre></div><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Ce que ça fait</strong><br><ul><li><code>create database</code> crée la base si elle n&#39;existe pas déjà. Le <code>if not exists</code> évite une erreur si vous réimportez une deuxième fois.</li><li><code>use</code> indique à MariaDB dans quelle base créer les tables qui suivent.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Pourquoi c&#39;est important</strong><br> Une fois ces deux lignes ajoutées, le fichier est <strong>autoportant</strong> : il recrée à lui seul la base complète, sur n&#39;importe quelle machine.<br> C&#39;est exactement ce qu&#39;on attend d&#39;un fichier remis dans un travail. </div><hr><h2 id="importer-une-base-de-donnees-dbeaver" tabindex="-1">Importer une base de données (DBeaver) <a class="header-anchor" href="#importer-une-base-de-donnees-dbeaver" aria-label="Permalink to &quot;Importer une base de données (DBeaver)&quot;">​</a></h2><p>Le fichier contient maintenant tout ce qu&#39;il faut :</p><ul><li>la création de la base de données (CREATE DATABASE)</li><li>la sélection de la base de données (USE)</li><li>la création des tables, contraintes et données</li></ul><p>Il suffit donc <strong>d&#39;exécuter le fichier SQL au complet</strong>. Le fichier contient des centaines d&#39;instructions : DBeaver les exécute toutes d&#39;un coup, dans l&#39;ordre.</p><hr><h3 id="etapes-d-importation" tabindex="-1">Étapes d&#39;importation <a class="header-anchor" href="#etapes-d-importation" aria-label="Permalink to &quot;Étapes d&#39;importation&quot;">​</a></h3><ul><li>Dans DBeaver, menu <code>Fichier</code> → <code>Ouvrir un fichier…</code>, puis choisir le fichier <code>.sql</code>. (Le glisser-déposer du fichier dans la fenêtre de DBeaver fonctionne aussi.)</li><li>Le fichier s&#39;ouvre dans un éditeur SQL. Vérifier dans la barre d&#39;outils que la <strong>connexion active</strong> est bien votre serveur MariaDB.</li><li>Exécuter <strong>tout le script</strong> avec <code>Alt + X</code> (menu <code>SQL Editor</code> → <code>Execute script</code>).</li><li>Rafraîchir le navigateur de bases de données avec <code>F5</code> : la base apparaît dans l&#39;arborescence.</li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>⚠️ <code>Alt + X</code>, et non <code>Ctrl + Entrée</code></strong><br><code>Ctrl + Entrée</code> exécute <strong>une seule instruction</strong> : celle où se trouve le curseur. Un fichier d&#39;import en contient des centaines. C&#39;est <code>Alt + X</code> (<em>Execute script</em>) qui les exécute toutes. </div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Erreur <code>No database selected</code></strong><br> Vous avez oublié d&#39;ajouter les deux lignes en haut du fichier. Revenez à la section précédente. </div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Des <code>?</code> à la place des accents ?</strong><br> Le fichier n&#39;a pas été lu en UTF-8. Vérifier l&#39;encodage dans les préférences de DBeaver, puis réimporter : une fois les <code>?</code> enregistrés dans la base, ils y restent et plus aucune requête ne retrouve « Bruno Lefèvre ». </div><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Attention</strong><br> Le script recrée les tables et écrase les données existantes.<br> S&#39;assurer que le fichier SQL correspond bien au travail à importer.<br> Encore une fois, toujours conserver une copie fonctionnelle des instructions que vous avez écrites pour votre travail. </div><hr><h2 id="demo" tabindex="-1">Démo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Démo&quot;">​</a></h2><ul><li>Exporter une base de données avec DBeaver.</li><li>Repérer le fichier <code>.sql</code> généré.</li><li>Ajouter le <code>create database</code> et le <code>use</code> au début du fichier.</li><li>Exécuter le fichier dans DBeaver avec <code>Alt + X</code>.</li><li>Vérifier que la base de données, les tables et les relations sont recréées.</li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4"> Si vous voulez être vraiment certain que ça fonctionne, supprimez manuellement votre base de données dans DBeaver avant d&#39;exécuter le script. </div><hr><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4"><ul class="list-disc pl-5"><li>Exporter = sauvegarder une base de données</li><li>Importer = recréer une base de données</li><li>L&#39;export de DBeaver <strong>n&#39;inclut pas</strong> le <code>create database</code> ni le <code>use</code> : il faut les ajouter au fichier</li><li>Un fichier bien préparé recrée la base à lui seul, sur n&#39;importe quelle machine</li><li>L&#39;export et l&#39;import se font tous les deux dans DBeaver</li></ul></div>`,44)])])}const v=r(n,[["render",d]]);export{g as __pageData,v as default};
